INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-15-owasp-top10-p1-1', 'doc-15-owasp-top10', 'doc-15-owasp-top10', 'Introduction', NULL, 'OWASP Top Ten Web Application Security Risks | OWASP Foundation For full functionality of this site it is necessary to enable JavaScript. Here are the instructions how to enable JavaScript in your web browser .', 'vec_doc-15-owasp-top10-p1-1', 0, 53, 'v2.1.0', 'd481c40f088d27e49a1c7ebe72f1aa55e08b892e8e85f5fc84526349ba6e55bd', '{"document_id":"doc-15-owasp-top10","document_title":"OWASP Top 10 Web Application Security Risks","chapter":"Specification","section":"Introduction","subsection":"UNKNOWN","table_id":null,"page":null,"domain":"WEB_SECURITY","authority_tier":0,"chunk_seq":1,"source_path":".zayron/knowledge/physical-15/15-owasp-top10.html","section_path":"Specification > Introduction"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-15-owasp-top10-p1-2', 'doc-15-owasp-top10', 'doc-15-owasp-top10', 'OWASP Top Ten Web Application Security Risks', NULL, 'The most current released version is the OWASP Top Ten 2025 . Previous versions are available at OWASP Top Ten 2021 and OWASP Top 10 2017 (PDF) . Older versiona are available in the Github repo . The OWASP Top 10 is a standard awareness document for developers and web application security. It represents a broad consensus about the most critical security risks to web applications. Globally recognized by developers as the first step towards more secure coding. Companies should adopt this document and start the process of ensuring that their web applications minimize these risks. Using the OWASP Top 10 is perhaps the most effective first step towards changing the software development culture within your organization into one that produces more secure code.', 'vec_doc-15-owasp-top10-p1-2', 0, 191, 'v2.1.0', '54168053596f289d9ff4c9f504e63a8fda11c08f9c2d745a9a2ef8b5ce552fbb', '{"document_id":"doc-15-owasp-top10","document_title":"OWASP Top 10 Web Application Security Risks","chapter":"Specification","section":"OWASP Top Ten Web Application Security Risks","subsection":"UNKNOWN","table_id":null,"page":null,"domain":"WEB_SECURITY","authority_tier":0,"chunk_seq":2,"source_path":".zayron/knowledge/physical-15/15-owasp-top10.html","section_path":"Specification > OWASP Top Ten Web Application Security Risks"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-15-owasp-top10-p1-3', 'doc-15-owasp-top10', 'doc-15-owasp-top10', 'Translation Efforts', NULL, 'Efforts have been made in numerous languages to translate the OWASP Top 10 - 2025. If you are interested in helping, please contact the members of the team for the language you are interested in contributing to, or if you don’t see your language listed (neither here nor at github ), please email [email&#160;protected] to let us know that you want to help and we’ll form a volunteer group for your language.', 'vec_doc-15-owasp-top10-p1-3', 0, 102, 'v2.1.0', '416f5e3bab7f2e9df1f77c7a34bb609815dd089bd75ce7c61b5610073f091fb9', '{"document_id":"doc-15-owasp-top10","document_title":"OWASP Top 10 Web Application Security Risks","chapter":"Specification","section":"Translation Efforts","subsection":"UNKNOWN","table_id":null,"page":null,"domain":"WEB_SECURITY","authority_tier":0,"chunk_seq":3,"source_path":".zayron/knowledge/physical-15/15-owasp-top10.html","section_path":"Specification > Translation Efforts"}');
