INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-15-owasp-top10-p1-15', 'doc-15-owasp-top10', 'doc-15-owasp-top10', '2021 Project Sponsors', NULL, 'The OWASP Top 10:2021 is sponsored by Secure Code Warrior.', 'vec_doc-15-owasp-top10-p1-15', 0, 15, 'v2.1.0', 'f19d0d0182fdfe4a44abec36df84c8c73f3faa0375fc10a1b9f379fac61a8cba', '{"document_id":"doc-15-owasp-top10","document_title":"OWASP Top 10 Web Application Security Risks","chapter":"Specification","section":"2021 Project Sponsors","subsection":"UNKNOWN","table_id":null,"page":null,"domain":"WEB_SECURITY","authority_tier":0,"chunk_seq":15,"source_path":".zayron/knowledge/physical-15/15-owasp-top10.html","section_path":"Specification > 2021 Project Sponsors"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-15-owasp-top10-p1-16', 'doc-15-owasp-top10', 'doc-15-owasp-top10', '2017 Project Sponsors', NULL, 'The OWASP Top 10 - 2017 project was sponsored by Autodesk, and supported by the OWASP NoVA Chapter .', 'vec_doc-15-owasp-top10-p1-16', 0, 25, 'v2.1.0', '1493c30cfed8cf69eaceb248716e45b099d144a2c9421016f4371968b5898f99', '{"document_id":"doc-15-owasp-top10","document_title":"OWASP Top 10 Web Application Security Risks","chapter":"Specification","section":"2017 Project Sponsors","subsection":"UNKNOWN","table_id":null,"page":null,"domain":"WEB_SECURITY","authority_tier":0,"chunk_seq":16,"source_path":".zayron/knowledge/physical-15/15-owasp-top10.html","section_path":"Specification > 2017 Project Sponsors"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-15-owasp-top10-p1-17', 'doc-15-owasp-top10', 'doc-15-owasp-top10', '2003-2013 Project Sponsors', NULL, 'Thanks to Aspect Security for sponsoring earlier versions.', 'vec_doc-15-owasp-top10-p1-17', 0, 15, 'v2.1.0', 'ab5449a1ca1a7fec7043ce519d114b986f7863dabb247b56f286b341c98a7c13', '{"document_id":"doc-15-owasp-top10","document_title":"OWASP Top 10 Web Application Security Risks","chapter":"Specification","section":"2003-2013 Project Sponsors","subsection":"UNKNOWN","table_id":null,"page":null,"domain":"WEB_SECURITY","authority_tier":0,"chunk_seq":17,"source_path":".zayron/knowledge/physical-15/15-owasp-top10.html","section_path":"Specification > 2003-2013 Project Sponsors"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-15-owasp-top10-p1-18', 'doc-15-owasp-top10', 'doc-15-owasp-top10', 'Goals', NULL, 'To collect the most comprehensive dataset related to identified application vulnerabilities to-date to enable analysis for the Top 10 and other future research as well. This data should come from a variety of sources; security vendors and consultancies, bug bounties, along with company/organizational contributions. Data will be normalized to allow for level comparison between Human assisted Tooling and Tooling assisted Humans.', 'vec_doc-15-owasp-top10-p1-18', 0, 108, 'v2.1.0', '2c2b7ddb7b27108642b74f4ea14682763ddf75b197e3bd1b1aa2f99f4c7579b6', '{"document_id":"doc-15-owasp-top10","document_title":"OWASP Top 10 Web Application Security Risks","chapter":"Specification","section":"Goals","subsection":"UNKNOWN","table_id":null,"page":null,"domain":"WEB_SECURITY","authority_tier":0,"chunk_seq":18,"source_path":".zayron/knowledge/physical-15/15-owasp-top10.html","section_path":"Specification > Goals"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-15-owasp-top10-p1-19', 'doc-15-owasp-top10', 'doc-15-owasp-top10', 'Analysis Infrastructure', NULL, 'Plan to leverage the OWASP Azure Cloud Infrastructure to collect, analyze, and store the data contributed.', 'vec_doc-15-owasp-top10-p1-19', 0, 27, 'v2.1.0', '90b22273ad135cba3a166192c728e75dd7ae6092ad5f5aa36f868f9dcbb98784', '{"document_id":"doc-15-owasp-top10","document_title":"OWASP Top 10 Web Application Security Risks","chapter":"Specification","section":"Analysis Infrastructure","subsection":"UNKNOWN","table_id":null,"page":null,"domain":"WEB_SECURITY","authority_tier":0,"chunk_seq":19,"source_path":".zayron/knowledge/physical-15/15-owasp-top10.html","section_path":"Specification > Analysis Infrastructure"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-15-owasp-top10-p1-20', 'doc-15-owasp-top10', 'doc-15-owasp-top10', 'Contributions', NULL, 'We plan to support both known and pseudo-anonymous contributions. The preference is for contributions to be known; this immensely helps with the validation/quality/confidence of the data submitted. If the submitter prefers to have their data stored anonymously and even go as far as submitting the data anonymously, then it will have to be classified as “unverified” vs. “verified”.', 'vec_doc-15-owasp-top10-p1-20', 0, 96, 'v2.1.0', '15a46bded7a3f963e122ef0574d895fabd174941d454a08eae8588736e4a774a', '{"document_id":"doc-15-owasp-top10","document_title":"OWASP Top 10 Web Application Security Risks","chapter":"Specification","section":"Contributions","subsection":"UNKNOWN","table_id":null,"page":null,"domain":"WEB_SECURITY","authority_tier":0,"chunk_seq":20,"source_path":".zayron/knowledge/physical-15/15-owasp-top10.html","section_path":"Specification > Contributions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-15-owasp-top10-p1-21', 'doc-15-owasp-top10', 'doc-15-owasp-top10', 'Contributions', NULL, 'Scenario 1: The submitter is known and has agreed to be identified as a contributing party. Scenario 2: The submitter is known but would rather not be publicly identified. Scenario 3: The submitter is known but does not want it recorded in the dataset.', 'vec_doc-15-owasp-top10-p1-21', 0, 63, 'v2.1.0', 'c7aa5d50fef6bdec81e4b5948babd774689bbc7f25f749ad84c2f9e9915db49d', '{"document_id":"doc-15-owasp-top10","document_title":"OWASP Top 10 Web Application Security Risks","chapter":"Specification","section":"Contributions","subsection":"Verified Data Contribution","table_id":null,"page":null,"domain":"WEB_SECURITY","authority_tier":0,"chunk_seq":21,"source_path":".zayron/knowledge/physical-15/15-owasp-top10.html","section_path":"Specification > Contributions > Verified Data Contribution"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-15-owasp-top10-p1-22', 'doc-15-owasp-top10', 'doc-15-owasp-top10', 'Contributions', NULL, 'Scenario 4: The submitter is anonymous. (Should we support?) The analysis of the data will be conducted with a careful distinction when the unverified data is part of the dataset that was analyzed.', 'vec_doc-15-owasp-top10-p1-22', 0, 50, 'v2.1.0', '9701d0497df402e58b156b35e8667c538867663aabe96cc1f1b497ff0282e6e1', '{"document_id":"doc-15-owasp-top10","document_title":"OWASP Top 10 Web Application Security Risks","chapter":"Specification","section":"Contributions","subsection":"Unverified Data Contribution","table_id":null,"page":null,"domain":"WEB_SECURITY","authority_tier":0,"chunk_seq":22,"source_path":".zayron/knowledge/physical-15/15-owasp-top10.html","section_path":"Specification > Contributions > Unverified Data Contribution"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-15-owasp-top10-p1-23', 'doc-15-owasp-top10', 'doc-15-owasp-top10', 'Contribution Process', NULL, 'There are a few ways that data can be contributed: Email a CSV/Excel file with the dataset(s) to [email&#160;protected] Upload a CSV/Excel file to https://bit.ly/OWASPTop10Data Template examples can be found in GitHub: https://github.com/OWASP/Top10/tree/master/2025/Data', 'vec_doc-15-owasp-top10-p1-23', 0, 68, 'v2.1.0', 'e514e22b94e9303feb2d5457f569544685da6e8f889211a26051d75e44718d79', '{"document_id":"doc-15-owasp-top10","document_title":"OWASP Top 10 Web Application Security Risks","chapter":"Specification","section":"Contribution Process","subsection":"UNKNOWN","table_id":null,"page":null,"domain":"WEB_SECURITY","authority_tier":0,"chunk_seq":23,"source_path":".zayron/knowledge/physical-15/15-owasp-top10.html","section_path":"Specification > Contribution Process"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-15-owasp-top10-p1-24', 'doc-15-owasp-top10', 'doc-15-owasp-top10', 'Contribution Period', NULL, 'We plan to accept contributions to the new Top 10 until July 31, 2025, for data dating from 2021 to 2024.', 'vec_doc-15-owasp-top10-p1-24', 0, 27, 'v2.1.0', 'cdfd77366a593ecc0a9309b44a6c58acb3341c885e7cfe966f3a8f601c2c5142', '{"document_id":"doc-15-owasp-top10","document_title":"OWASP Top 10 Web Application Security Risks","chapter":"Specification","section":"Contribution Period","subsection":"UNKNOWN","table_id":null,"page":null,"domain":"WEB_SECURITY","authority_tier":0,"chunk_seq":24,"source_path":".zayron/knowledge/physical-15/15-owasp-top10.html","section_path":"Specification > Contribution Period"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-15-owasp-top10-p1-25', 'doc-15-owasp-top10', 'doc-15-owasp-top10', 'Data Structure', NULL, 'The following data elements are required or optional. The more information provided the more accurate our analysis can be. At a bare minimum, we need the time period, total number of applications tested in the dataset, and the list of CWEs and counts of how many applications contained that CWE. If at all possible, please provide the additional metadata, because that will greatly help us gain more insights into the current state of testing and vulnerabilities.', 'vec_doc-15-owasp-top10-p1-25', 0, 116, 'v2.1.0', '303c85ac6040285af022e35c35688ae1dd5ec9d025f646a941dbfad2b67bc5f9', '{"document_id":"doc-15-owasp-top10","document_title":"OWASP Top 10 Web Application Security Risks","chapter":"Specification","section":"Data Structure","subsection":"UNKNOWN","table_id":null,"page":null,"domain":"WEB_SECURITY","authority_tier":0,"chunk_seq":25,"source_path":".zayron/knowledge/physical-15/15-owasp-top10.html","section_path":"Specification > Data Structure"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-15-owasp-top10-p1-26', 'doc-15-owasp-top10', 'doc-15-owasp-top10', 'Data Structure', NULL, 'Contributor Name (org or anon) Contributor Contact Email Time period (2024, 2023, 2022, 2021) Number of applications tested Type of testing (TaH, HaT, Tools) Primary Language (code) Geographic Region (Global, North America, EU, Asia, other) Primary Industry (Multiple, Financial, Industrial, Software, ??) Whether or not data contains retests or the same applications multiple times (T/F)', 'vec_doc-15-owasp-top10-p1-26', 0, 97, 'v2.1.0', 'a198281615fc48108aa13acbb3c24165d64361e8699992569da0d3d39add9341', '{"document_id":"doc-15-owasp-top10","document_title":"OWASP Top 10 Web Application Security Risks","chapter":"Specification","section":"Data Structure","subsection":"Metadata","table_id":null,"page":null,"domain":"WEB_SECURITY","authority_tier":0,"chunk_seq":26,"source_path":".zayron/knowledge/physical-15/15-owasp-top10.html","section_path":"Specification > Data Structure > Metadata"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-15-owasp-top10-p1-27', 'doc-15-owasp-top10', 'doc-15-owasp-top10', 'Data Structure', NULL, 'A list of CWEs w/ count of applications found to contain that CWE If at all possible, please provide core CWEs in the data, not CWE categories. This will help with the analysis, any normalization/aggregation done as a part of this analysis will be well documented.', 'vec_doc-15-owasp-top10-p1-27', 0, 66, 'v2.1.0', '694ae34109da55502fbd5f62f8f208ee47b9c79345cdaea55b7ab41e30333b57', '{"document_id":"doc-15-owasp-top10","document_title":"OWASP Top 10 Web Application Security Risks","chapter":"Specification","section":"Data Structure","subsection":"CWE Data","table_id":null,"page":null,"domain":"WEB_SECURITY","authority_tier":0,"chunk_seq":27,"source_path":".zayron/knowledge/physical-15/15-owasp-top10.html","section_path":"Specification > Data Structure > CWE Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-15-owasp-top10-p1-28', 'doc-15-owasp-top10', 'doc-15-owasp-top10', 'Data Structure', NULL, 'If a contributor has two types of datasets, one from HaT and one from TaH sources, then it is recommended to submit them as two separate datasets. HaT = Human assisted Tools (higher volume/frequency, primarily from tooling) TaH = Tool assisted Human (lower volume/frequency, primarily from human testing)', 'vec_doc-15-owasp-top10-p1-28', 0, 76, 'v2.1.0', '104f79d84d751fac71430e27437fda52105580de6f3b85a4324af05f324fab41', '{"document_id":"doc-15-owasp-top10","document_title":"OWASP Top 10 Web Application Security Risks","chapter":"Specification","section":"Data Structure","subsection":"Note:","table_id":null,"page":null,"domain":"WEB_SECURITY","authority_tier":0,"chunk_seq":28,"source_path":".zayron/knowledge/physical-15/15-owasp-top10.html","section_path":"Specification > Data Structure > Note:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-15-owasp-top10-p1-29', 'doc-15-owasp-top10', 'doc-15-owasp-top10', 'Survey', NULL, 'Similarly to the Top Ten 2021, we plan to conduct a survey to identify up to two categories of the Top Ten that the community believes are important, but may not be reflected in the data yet. We plan to conduct the survey in early 2025, and will be utilizing Google forms in a similar manner as last time. The CWEs on the survey will come from current trending findings, CWEs that are outside the Top Ten in data, and other potential sources.', 'vec_doc-15-owasp-top10-p1-29', 0, 111, 'v2.1.0', 'f82d9bba87dc4b254d7836fbf54bc3abea7825a32fda531bf300fc01a49c6780', '{"document_id":"doc-15-owasp-top10","document_title":"OWASP Top 10 Web Application Security Risks","chapter":"Specification","section":"Survey","subsection":"UNKNOWN","table_id":null,"page":null,"domain":"WEB_SECURITY","authority_tier":0,"chunk_seq":29,"source_path":".zayron/knowledge/physical-15/15-owasp-top10.html","section_path":"Specification > Survey"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-15-owasp-top10-p1-30', 'doc-15-owasp-top10', 'doc-15-owasp-top10', 'Process', NULL, 'At a high level, we plan to perform a level of data normalization; however, we will keep a version of the raw data contributed for future analysis. We will analyze the CWE distribution of the datasets and potentially reclassify some CWEs to consolidate them into larger buckets. We will carefully document all normalization actions taken so it is clear what has been done. We plan to calculate likelihood following the model we continued in 2021 to determine incidence rate instead of frequency to rate how likely a given app may contain at least one instance of a CWE. This means we aren’t looking for the frequency rate (number of findings) in an app, rather, we are looking for the number of applications that had one or more instances of a CWE. We can calculate the incidence rate based on the total number of applications tested in the dataset compared to how many applications each CWE was found in. In addition, we will be developing base CWSS scores for the top 20-30 CWEs and include potential impact into the Top 10 weighting. Also, would like to explore additional insights that could be gleaned from the contributed dataset to see what else can be learned that could be of use to the security and development communities. Watch Star The OWASP &reg; Foundation works to improve the security of software through its community-led open source software projects, hundreds of chapters worldwide, tens of thousands of members, and by hosting local and global conferences.', 'vec_doc-15-owasp-top10-p1-30', 0, 370, 'v2.1.0', '063ee9a25c039e03b2bcb759b16baee233d5a20b9aeea54557f1239f3611f745', '{"document_id":"doc-15-owasp-top10","document_title":"OWASP Top 10 Web Application Security Risks","chapter":"Specification","section":"Process","subsection":"UNKNOWN","table_id":null,"page":null,"domain":"WEB_SECURITY","authority_tier":0,"chunk_seq":30,"source_path":".zayron/knowledge/physical-15/15-owasp-top10.html","section_path":"Specification > Process"}');
